const STATIC_ASSETS:Record<string,string>={"index.html":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#263b2d\">\n  <meta name=\"description\" content=\"پادناکِشت؛ محصولات محلی روستای خفر پادنا، از دل طبیعت دنا.\">\n  <meta property=\"og:title\" content=\"پادناکِشت | از دل طبیعت دنا\">\n  <meta property=\"og:description\" content=\"محصولات محلی پادنا، مستقیم از تولیدکنندگان روستا.\">\n  <meta property=\"og:type\" content=\"website\">\n  <title>پادناکِشت | از دل طبیعت دنا</title>\n  <link rel=\"stylesheet\" href=\"./styles.css\">\n  <script src=\"./app.js\" defer></script>\n</head>\n<body>\n  <div class=\"announcement\">محصولات محلی پادنا، از دست تولیدکنندگان روستا</div>\n  <header class=\"site-header\">\n    <a class=\"brand\" href=\"./\" aria-label=\"پادناکِشت، صفحه اصلی\">\n      <span class=\"brand-mark\">پ</span>\n      <span class=\"brand-copy\"><strong>پادناکِشت</strong><small>از دل طبیعت دنا</small></span>\n    </a>\n    <nav class=\"desktop-nav\" aria-label=\"منوی اصلی\">\n      <a href=\"#products\">محصولات</a>\n      <a href=\"#story\">قصه پادنا</a>\n      <a href=\"#how-to-order\">راهنمای سفارش</a>\n    </nav>\n    <div class=\"header-actions\">\n      <a class=\"icon-link\" href=\"#track-order\">پیگیری سفارش</a>\n      <button class=\"cart-trigger\" id=\"cart-open\" type=\"button\" aria-label=\"باز کردن سبد خرید\">\n        <span>سبد خرید</span><b id=\"cart-count\">۰</b>\n      </button>\n    </div>\n  </header>\n\n  <main>\n    <section class=\"hero\">\n      <div class=\"hero-copy\">\n        <span class=\"eyebrow\"><i></i> از روستای خفر پادنا</span>\n        <h1>طعمِ آشنا،<br><em>از دل طبیعت دنا</em></h1>\n        <p>محصولاتی که در خانه‌ها و کارگاه‌های کوچک پادنا آماده می‌شوند؛ بی‌واسطه از تولیدکنندگان روستا به دست شما می‌رسند.</p>\n        <a class=\"button button-light\" href=\"#products\">دیدن محصولات <span aria-hidden=\"true\">←</span></a>\n        <div class=\"hero-note\"><span class=\"note-line\"></span><span>اهل پادنا؛ با دست‌های خودمان</span></div>\n      </div>\n      <div class=\"hero-visual\">\n        <div class=\"hero-photo-frame\">\n          <img src=\"https://images.pexels.com/photos/36418624/pexels-photo-36418624.jpeg?cs=srgb&dl=pexels-edita-brus-2027796741-36418624.jpg&fm=jpg\" alt=\"تصویر نمایشی گردوهای مغز شده\">\n        </div>\n        <div class=\"hero-stamp\"><span>پادنا</span><small>طبیعت، کار و زندگی</small></div>\n        <span class=\"hero-orbit orbit-one\"></span><span class=\"hero-orbit orbit-two\"></span>\n      </div>\n      <div class=\"hero-index\">01 <span>/</span> 03</div>\n    </section>\n\n    <section class=\"trust-strip\" aria-label=\"ویژگی‌های فروشگاه\">\n      <div><span class=\"trust-number\">۰۱</span><p><strong>از تولیدکننده</strong><small>بدون واسطه‌فروشی</small></p></div>\n      <div><span class=\"trust-number\">۰۲</span><p><strong>ریشه در پادنا</strong><small>محصولات روستای خفر</small></p></div>\n      <div><span class=\"trust-number\">۰۳</span><p><strong>هماهنگی پیش از تأیید</strong><small>قیمت، موجودی و ارسال شفاف</small></p></div>\n    </section>\n\n    <section class=\"products-section section-wrap\" id=\"products\">\n      <div class=\"section-heading\">\n        <div><span class=\"eyebrow\">چیزهایی از پادنا</span><h2>محصولات <em>ما</em></h2></div>\n        <p>هر محصول، قصه‌ای از زمین و دست‌های زحمت‌کش روستاست. قیمت و موجودی روز پیش از تأیید سفارش با شما هماهنگ می‌شود. عکس‌های فعلی نمایشی‌اند و عکس اختصاصی محصولات پادناکِشت نیستند.</p>\n      </div>\n      <div class=\"catalog-toolbar\">\n        <div class=\"category-filters\" id=\"category-filters\">\n          <button class=\"filter-chip active\" data-category=\"all\" type=\"button\">همه محصولات</button>\n        </div>\n        <span class=\"catalog-count\" id=\"catalog-count\">در حال دریافت محصولات…</span>\n      </div>\n      <div class=\"product-grid\" id=\"product-grid\" aria-live=\"polite\">\n        <div class=\"loading-state\">در حال آماده‌کردن قفسه‌های پادنا…</div>\n      </div>\n    </section>\n\n    <section class=\"story-section\" id=\"story\">\n      <div class=\"story-image\">\n        <img src=\"https://images.pexels.com/photos/7404564/pexels-photo-7404564.jpeg?cs=srgb&dl=pexels-michaelbayazidi-7404564.jpg&fm=jpg\" alt=\"تصویر نمایشی از یک روستای کوهستانی ایران؛ عکس اختصاصی خفر نیست\">\n        <span class=\"image-caption\">تصویر نمونه از روستاهای کوهستانی ایران؛ عکس اختصاصی خفر نیست</span>\n      </div>\n      <div class=\"story-copy\">\n        <span class=\"eyebrow\">قصه‌ای از خفر</span>\n        <h2>از دل روستا،<br><em>با دست‌های خودمان</em></h2>\n        <p>پادناکِشت از دل روستای خفر پادنا شکل گرفته؛ جایی که محصول، حاصل فصل و زحمت آدم‌هایی است که سال‌هاست با زمین و طبیعت زندگی می‌کنند.</p>\n        <p>ما محصولات را از خود تولیدکنندگان روستا معرفی و عرضه می‌کنیم؛ ساده و روشن، همان‌طور که هست.</p>\n        <div class=\"signature\">پادناکِشت <span>از دل طبیعت دنا</span></div>\n      </div>\n    </section>\n\n    <section class=\"how-section section-wrap\" id=\"how-to-order\">\n      <div class=\"section-heading compact\">\n        <div><span class=\"eyebrow\">خرید بی‌دردسر</span><h2>چطور <em>سفارش بدهم؟</em></h2></div>\n        <p>ثبت درخواست در سایت به معنی تأیید نهایی قیمت یا موجودی نیست؛ همه جزئیات قبل از قطعی‌شدن سفارش با شما هماهنگ می‌شود.</p>\n      </div>\n      <div class=\"steps-grid\">\n        <article><span>۱</span><h3>انتخاب محصول</h3><p>محصولات دلخواه را به سبد خرید اضافه کنید و مقدار را مشخص کنید.</p></article>\n        <article><span>۲</span><h3>ثبت درخواست</h3><p>نام، شماره تماس و نشانی تحویل را وارد کنید تا درخواست شما ثبت شود.</p></article>\n        <article><span>۳</span><h3>هماهنگی نهایی</h3><p>قیمت روز، موجودی و هزینه ارسال با شما بررسی و تأیید می‌شود.</p></article>\n      </div>\n    </section>\n\n    <section class=\"track-section\" id=\"track-order\">\n      <div class=\"track-copy\"><span class=\"eyebrow\">سفارش قبلی</span><h2>پیگیری <em>سفارش</em></h2><p>کد سفارشی را که پس از ثبت درخواست دریافت کرده‌اید، همراه شماره تماس وارد کنید.</p></div>\n      <form id=\"track-form\" class=\"track-form\">\n        <label>کد سفارش<input name=\"code\" placeholder=\"مثلاً PK-A1B2C3D4\" required autocomplete=\"off\"></label>\n        <label>شماره تماس<input name=\"phone\" placeholder=\"شماره‌ای که ثبت کرده‌اید\" required inputmode=\"tel\" autocomplete=\"tel\"></label>\n        <button class=\"button button-dark\" type=\"submit\">پیگیری وضعیت</button>\n        <p class=\"form-feedback\" id=\"track-feedback\" role=\"status\"></p>\n      </form>\n    </section>\n\n    <section class=\"contact-band\">\n      <div><span class=\"eyebrow\">حرفی، پرسشی، سفارشی؟</span><h2>ما از همان حوالیِ پادنا هستیم.</h2></div>\n      <div class=\"contact-meta\"><span>ایتا</span><strong>@Padena_kesht1</strong><small>برای هماهنگی و پرسش درباره محصولات</small></div>\n    </section>\n  </main>\n\n  <footer class=\"site-footer\">\n    <a class=\"brand footer-brand\" href=\"./\"><span class=\"brand-mark\">پ</span><span class=\"brand-copy\"><strong>پادناکِشت</strong><small>از دل طبیعت دنا</small></span></a>\n    <p>محصولات محلی پادنا، از تولیدکنندگان روستای خفر.</p>\n    <a class=\"footer-copy\" href=\"./credits.html\">اعتبار تصاویر</a><span class=\"footer-copy\">© پادناکِشت</span>\n  </footer>\n\n  <div class=\"drawer-backdrop\" id=\"drawer-backdrop\" hidden></div>\n  <aside class=\"cart-drawer\" id=\"cart-drawer\" aria-label=\"سبد خرید\" aria-hidden=\"true\">\n    <div class=\"drawer-head\"><div><span class=\"eyebrow\">انتخاب‌های شما</span><h2>سبد خرید</h2></div><button class=\"close-button\" id=\"cart-close\" type=\"button\" aria-label=\"بستن\">×</button></div>\n    <div class=\"cart-lines\" id=\"cart-lines\"><div class=\"empty-cart\">هنوز محصولی انتخاب نکرده‌اید.</div></div>\n    <div class=\"drawer-footer\"><div class=\"cart-estimate\"><span>جمع برآوردی کالاها</span><strong id=\"cart-subtotal\">پس از تأیید قیمت</strong></div><p>هزینه ارسال و مبلغ نهایی پیش از تأیید سفارش اعلام می‌شود.</p><button class=\"button button-dark full-width\" id=\"checkout-open\" type=\"button\" disabled>ادامه و ثبت درخواست</button></div>\n  </aside>\n\n  <div class=\"modal-backdrop\" id=\"checkout-modal\" hidden>\n    <section class=\"checkout-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"checkout-title\">\n      <div class=\"modal-head\"><div><span class=\"eyebrow\">یک قدم تا هماهنگی</span><h2 id=\"checkout-title\">اطلاعات سفارش</h2></div><button class=\"close-button\" id=\"checkout-close\" type=\"button\" aria-label=\"بستن\">×</button></div>\n      <form id=\"checkout-form\" class=\"checkout-form\">\n        <div class=\"form-row\"><label>نام و نام خانوادگی<input name=\"customerName\" required maxlength=\"100\" autocomplete=\"name\"></label><label>شماره تماس<input name=\"phone\" required maxlength=\"24\" inputmode=\"tel\" autocomplete=\"tel\"></label></div>\n        <div class=\"form-row\"><label>شهر<input name=\"city\" required maxlength=\"80\" autocomplete=\"address-level2\"></label><label>روش تحویل<select name=\"deliveryMethod\" required><option value=\"isfahan\">تحویل در اصفهان</option><option value=\"post\">ارسال به شهرهای دیگر</option></select></label></div>\n        <label>نشانی کامل<textarea name=\"address\" required minlength=\"5\" maxlength=\"500\" rows=\"3\" autocomplete=\"street-address\"></textarea></label>\n        <label>توضیحات بیشتر <span class=\"optional\">(اختیاری)</span><textarea name=\"notes\" maxlength=\"500\" rows=\"2\" placeholder=\"مثلاً زمان مناسب تماس یا توضیح سفارش\"></textarea></label>\n        <div class=\"checkout-notice\">پس از ثبت درخواست، قیمت روز، موجودی و هزینه ارسال با شما هماهنگ می‌شود. تا پیش از تأیید نهایی، پرداختی انجام ندهید.</div>\n        <p class=\"form-feedback\" id=\"checkout-feedback\" role=\"status\"></p>\n        <button class=\"button button-dark full-width\" type=\"submit\">ثبت درخواست خرید</button>\n      </form>\n    </section>\n  </div>\n\n  <div class=\"modal-backdrop\" id=\"success-modal\" hidden>\n    <section class=\"success-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"success-title\">\n      <div class=\"success-mark\">✓</div><span class=\"eyebrow\">درخواست دریافت شد</span><h2 id=\"success-title\">ممنون از انتخابت</h2>\n      <p id=\"success-message\">درخواست شما ثبت شد.</p>\n      <div class=\"order-code\"><small>کد پیگیری سفارش</small><strong id=\"success-code\"></strong><button id=\"copy-order-code\" type=\"button\">کپی کد</button></div>\n      <button class=\"button button-dark full-width\" id=\"success-close\" type=\"button\">بازگشت به فروشگاه</button>\n    </section>\n  </div>\n</body>\n</html>","admin.html":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex,nofollow\"><meta name=\"theme-color\" content=\"#263b2d\">\n  <title>مدیریت فروشگاه | پادناکِشت</title>\n  <link rel=\"stylesheet\" href=\"./styles.css\"><link rel=\"stylesheet\" href=\"./admin.css\">\n  <script src=\"./admin.js\" defer></script>\n</head>\n<body class=\"admin-body\">\n  <header class=\"admin-header\"><a class=\"brand\" href=\"./\"><span class=\"brand-mark\">پ</span><span class=\"brand-copy\"><strong>پادناکِشت</strong><small>پنل مدیریت فروشگاه</small></span></a><a href=\"./\" class=\"back-link\" aria-label=\"بازگشت به فروشگاه اصلی\">مشاهده فروشگاه ↗</a></header>\n  <main class=\"admin-wrap\">\n    <section class=\"login-card\" id=\"setup-card\" hidden>\n      <span class=\"eyebrow\">راه‌اندازی نخستین مدیر</span><h1>ساخت گذرواژه مدیر</h1><p>کد یک‌بارمصرف راه‌اندازی را وارد کنید و گذرواژه اختصاصی خودتان را بسازید.</p>\n      <form id=\"setup-form\">\n        <label>کد یک‌بارمصرف<input name=\"setupToken\" type=\"password\" required autocomplete=\"off\"></label>\n        <label>گذرواژه جدید<input name=\"password\" type=\"password\" required minlength=\"12\" maxlength=\"128\" autocomplete=\"new-password\"></label>\n        <label>تکرار گذرواژه<input name=\"passwordConfirm\" type=\"password\" required minlength=\"12\" maxlength=\"128\" autocomplete=\"new-password\"></label>\n        <p class=\"form-feedback\" id=\"setup-feedback\" role=\"status\"></p>\n        <button class=\"button button-dark full-width\" type=\"submit\">راه‌اندازی پنل مدیریت</button>\n      </form>\n    </section>\n    <section class=\"login-card\" id=\"login-card\" hidden>\n      <span class=\"eyebrow\">دسترسی محدود</span><h1>ورود مدیر</h1><p>برای مدیریت محصولات و سفارش‌ها، گذرواژه مدیر را وارد کنید.</p>\n      <form id=\"login-form\"><label>گذرواژه<input name=\"password\" type=\"password\" required autocomplete=\"current-password\"></label><p class=\"form-feedback\" id=\"login-feedback\" role=\"status\"></p><button class=\"button button-dark full-width\" type=\"submit\">ورود به پنل</button></form>\n    </section>\n    <section id=\"admin-dashboard\" hidden>\n      <div class=\"admin-title\"><div><span class=\"eyebrow\">مدیریت فروشگاه</span><h1>داشبورد پادناکِشت</h1></div><button class=\"button button-outline\" id=\"logout-button\" type=\"button\" aria-label=\"خروج امن از پنل مدیریت\">خروج امن</button></div>\n      <div class=\"admin-tabs\"><button class=\"active\" data-tab=\"orders\" type=\"button\">سفارش‌ها</button><button data-tab=\"products\" type=\"button\">محصولات</button></div>\n      <section class=\"admin-panel\" id=\"orders-panel\"><div class=\"panel-title\"><h2>درخواست‌های خرید</h2><button class=\"text-button\" id=\"orders-refresh\" type=\"button\">به‌روزرسانی</button></div><div id=\"orders-list\"><p class=\"loading-state\">در حال دریافت سفارش‌ها…</p></div></section>\n      <section class=\"admin-panel\" id=\"products-panel\" hidden><div class=\"panel-title\"><h2>فهرست محصولات</h2><button class=\"text-button\" id=\"products-refresh\" type=\"button\">به‌روزرسانی</button></div><div id=\"products-list\"></div></section>\n      <p class=\"admin-footnote\">قیمت‌ها و موجودی‌ها باید از اطلاعات واقعی روز وارد شوند. تأیید سفارش، موجودی کالاها را در پایگاه داده رزرو می‌کند.</p>\n    </section>\n  </main>\n</body>\n</html>","credits.html":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"robots\" content=\"index,follow\"><meta name=\"theme-color\" content=\"#263b2d\">\n  <title>اعتبار تصاویر | پادناکِشت</title><link rel=\"stylesheet\" href=\"./styles.css\">\n</head>\n<body>\n  <header class=\"site-header\">\n    <a class=\"brand\" href=\"./\"><span class=\"brand-mark\">پ</span><span class=\"brand-copy\"><strong>پادناکِشت</strong><small>از دل طبیعت دنا</small></span></a>\n    <a class=\"icon-link\" href=\"./\">بازگشت به فروشگاه</a>\n  </header>\n  <main class=\"credits-wrap\">\n    <span class=\"eyebrow\">شفافیت در تصویر</span>\n    <h1>اعتبار تصاویر</h1>\n    <p class=\"credits-intro\">تصاویر این نسخه از کتابخانه عکس‌های رایگان Pexels انتخاب شده‌اند. این عکس‌ها فقط برای نمایش نمونه و حال‌وهوای محصول به کار رفته‌اند؛ عکس واقعی کالاها، بسته‌بندی یا تولیدکنندگان پادناکِشت نیستند. عکس اختصاصی هر محصول باید در نسخه نهایی جایگزین شود.</p>\n    <ul class=\"credits-list\">\n      <li><strong>گردو</strong><span>تصویر از Edita Brus</span><a href=\"https://images.pexels.com/photos/36418624/pexels-photo-36418624.jpeg?cs=srgb&dl=pexels-edita-brus-2027796741-36418624.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>عسل</strong><span>تصویر از Adonyi Gábor</span><a href=\"https://images.pexels.com/photos/5634203/pexels-photo-5634203.jpeg?cs=srgb&dl=pexels-adonyi-foto-5634203.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>لوبیا</strong><span>تصویر از Leeloo The First</span><a href=\"https://images.pexels.com/photos/5228850/pexels-photo-5228850.jpeg?cs=srgb&dl=pexels-leeloothefirst-5228850.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>سرکه</strong><span>تصویر از Roman Odintsov</span><a href=\"https://images.pexels.com/photos/7493940/pexels-photo-7493940.jpeg?cs=srgb&dl=pexels-roman-odintsov-7493940.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>پنیر</strong><span>تصویر از Jaralol</span><a href=\"https://images.pexels.com/photos/19460144/pexels-photo-19460144.jpeg?cs=srgb&dl=pexels-jaralol-19460144.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>انجیر خشک</strong><span>تصویر از SHKRABA Anthony</span><a href=\"https://images.pexels.com/photos/4499221/pexels-photo-4499221.jpeg?cs=srgb&dl=pexels-shkrabaanthony-4499221.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>توت خشک</strong><span>تصویر از SHKRABA Anthony</span><a href=\"https://images.pexels.com/photos/4499220/pexels-photo-4499220.jpeg?cs=srgb&dl=pexels-shkrabaanthony-4499220.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>خرما</strong><span>تصویر از Visual Stories</span><a href=\"https://images.pexels.com/photos/20520971/pexels-photo-20520971.jpeg?cs=srgb&dl=pexels-visualstoriesbytugba-20520971.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>انگور قرمز</strong><span>تصویر از Andres Alaniz</span><a href=\"https://images.pexels.com/photos/21193087/pexels-photo-21193087.jpeg?cs=srgb&dl=pexels-andres-alaniz-461433202-21193087.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>سیب</strong><span>تصویر از Hatice Noğman</span><a href=\"https://images.pexels.com/photos/14833258/pexels-photo-14833258.jpeg?cs=srgb&dl=pexels-nogman-14833258.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>کنجد</strong><span>تصویر از Ivan S</span><a href=\"https://images.pexels.com/photos/8951047/pexels-photo-8951047.jpeg?cs=srgb&dl=pexels-ivan-s-8951047.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>ماست، تصویر نمایشی لبنیات</strong><span>تصویر از elif tekkaya</span><a href=\"https://images.pexels.com/photos/10809146/pexels-photo-10809146.jpeg?cs=srgb&dl=pexels-eliftekkaya-10809146.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>انگور سبز</strong><span>تصویر از Cup of Couple</span><a href=\"https://images.pexels.com/photos/7656754/pexels-photo-7656754.jpeg?cs=srgb&dl=pexels-cup-of-couple-7656754.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n      <li><strong>روستای کوهستانی، تصویر نمونه</strong><span>تصویر از Michael Bayazidi؛ عکس خفر پادنا نیست</span><a href=\"https://images.pexels.com/photos/7404564/pexels-photo-7404564.jpeg?cs=srgb&dl=pexels-michaelbayazidi-7404564.jpg&fm=jpg\" target=\"_blank\" rel=\"noreferrer\">مشاهده تصویر</a></li>\n    </ul>\n    <p class=\"credits-license\">مجوز استفاده: <a href=\"https://www.pexels.com/license/\" target=\"_blank\" rel=\"noreferrer\">Pexels License</a></p>\n  </main>\n  <footer class=\"site-footer\"><a class=\"brand footer-brand\" href=\"./\"><span class=\"brand-mark\">پ</span><span class=\"brand-copy\"><strong>پادناکِشت</strong><small>از دل طبیعت دنا</small></span></a><p>محصولات محلی پادنا، از تولیدکنندگان روستای خفر.</p><span class=\"footer-copy\">© پادناکِشت</span></footer>\n</body>\n</html>","styles.css":":root{\n  --forest:#263b2d;--forest-2:#344d3a;--moss:#6f7957;--cream:#f5f1e8;--paper:#fbf9f4;\n  --sand:#e8dfcf;--clay:#b86d4b;--ink:#272a24;--muted:#77796e;--line:#ded8cb;\n  --shadow:0 18px 50px rgba(39,42,36,.10);--radius:22px;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth;scroll-padding-top:90px}\nbody{margin:0;background:var(--paper);color:var(--ink);font-family:Vazirmatn,Tahoma,\"Segoe UI\",sans-serif;line-height:1.8}\nbutton,input,textarea,select{font:inherit}\nbutton,a{-webkit-tap-highlight-color:transparent}\na{color:inherit;text-decoration:none}\nbutton{cursor:pointer}\nimg{display:block;max-width:100%}\n.announcement{padding:7px 16px;text-align:center;background:var(--forest);color:#f4eee2;font-size:12px;letter-spacing:.02em}\n.site-header{height:82px;padding:0 clamp(18px,5vw,76px);display:flex;align-items:center;justify-content:space-between;background:rgba(251,249,244,.96);border-bottom:1px solid rgba(38,59,45,.08);position:sticky;top:0;z-index:20;backdrop-filter:blur(12px)}\n.brand{display:inline-flex;align-items:center;gap:11px;min-width:170px}\n.brand-mark{width:42px;height:42px;display:grid;place-items:center;border:1px solid var(--clay);border-radius:50%;color:var(--forest);font-size:22px;font-weight:700}\n.brand-copy{display:grid;line-height:1.35}\n.brand-copy strong{font-size:17px;color:var(--forest);letter-spacing:-.04em}\n.brand-copy small{font-size:10px;color:var(--muted);letter-spacing:.05em}\n.desktop-nav{display:flex;gap:34px;font-size:13px;color:#585d52}\n.desktop-nav a,.icon-link{transition:color .2s}\n.desktop-nav a:hover,.icon-link:hover{color:var(--clay)}\n.header-actions{display:flex;align-items:center;gap:22px}\n.icon-link{font-size:12px;color:#5e6259}\n.cart-trigger{border:1px solid var(--forest);background:var(--forest);color:#fff;border-radius:999px;padding:9px 15px;display:flex;align-items:center;gap:12px;font-size:12px}\n.cart-trigger b{width:22px;height:22px;display:grid;place-items:center;background:#e5d7bd;color:var(--forest);border-radius:50%;font-size:11px}\n.hero{position:relative;min-height:560px;background:var(--forest);color:#f7f1e5;padding:70px clamp(24px,10vw,150px) 76px;display:grid;grid-template-columns:1fr 1fr;align-items:center;overflow:hidden}\n.hero:before{content:\"\";position:absolute;width:620px;height:620px;border:1px solid rgba(238,225,201,.13);border-radius:50%;right:-210px;top:-250px}\n.hero:after{content:\"\";position:absolute;width:420px;height:420px;border:1px solid rgba(238,225,201,.11);border-radius:50%;left:-160px;bottom:-260px}\n.hero-copy{position:relative;z-index:2;max-width:510px}\n.eyebrow{display:inline-flex;align-items:center;gap:9px;color:var(--clay);font-size:11px;letter-spacing:.04em;font-weight:600}\n.hero .eyebrow{color:#d4b68c}\n.hero .eyebrow i{width:6px;height:6px;border-radius:50%;background:#d4b68c}\n.hero h1{font-size:clamp(42px,5.5vw,76px);line-height:1.35;letter-spacing:-.055em;margin:20px 0 18px;font-weight:800}\n.hero h1 em,.section-heading h2 em,.story-copy h2 em,.track-copy h2 em{font-style:normal;color:#d7b98e}\n.hero-copy>p{max-width:430px;color:#d5d5c8;font-size:14px;line-height:2.2;margin:0 0 28px}\n.button{display:inline-flex;align-items:center;justify-content:center;gap:15px;border:0;border-radius:999px;padding:13px 24px;font-size:13px;font-weight:600;min-height:48px;transition:background .2s,color .2s,opacity .2s}\n.button-light{background:#e9ddc8;color:var(--forest)}\n.button-light:hover{background:#fff}\n.button-dark{background:var(--forest);color:#fff}\n.button-dark:hover{background:#3b5843}\n.button-outline{background:transparent;border:1px solid var(--line);color:var(--forest)}\n.button:disabled{opacity:.45;cursor:not-allowed}\n.hero-note{display:flex;align-items:center;gap:12px;margin-top:40px;color:#c2c4b6;font-size:11px}\n.note-line{width:36px;height:1px;background:#b8a37e}\n.hero-visual{position:relative;z-index:2;justify-self:center;width:min(390px,90%);height:390px}\n.hero-photo-frame{position:absolute;inset:20px 25px 20px 12px;padding:12px;background:#eee6d7;box-shadow:0 25px 70px rgba(0,0,0,.28);transform:rotate(2deg)}\n.hero-photo-frame img{width:100%;height:100%;object-fit:cover}\n.hero-stamp{position:absolute;left:-18px;bottom:18px;width:126px;height:126px;border-radius:50%;background:#d7b98e;color:var(--forest);display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 12px 30px rgba(0,0,0,.16);transform:rotate(-9deg)}\n.hero-stamp span{font-size:28px;font-weight:800}\n.hero-stamp small{font-size:10px}\n.hero-orbit{position:absolute;border:1px solid rgba(228,213,188,.4);border-radius:50%;pointer-events:none}\n.orbit-one{width:440px;height:440px;top:-7px;left:-5px}\n.orbit-two{width:490px;height:490px;top:-30px;left:-30px;border-style:dashed;opacity:.45}\n.hero-index{position:absolute;bottom:25px;right:clamp(24px,5vw,76px);font-size:12px;color:#c3c3b7;letter-spacing:.1em}\n.hero-index span{color:#b98b62;margin:0 5px}\n.trust-strip{display:grid;grid-template-columns:repeat(3,1fr);padding:28px clamp(24px,10vw,150px);background:#eee8dc;border-bottom:1px solid var(--line)}\n.trust-strip>div{display:flex;align-items:center;justify-content:center;gap:14px;border-left:1px solid #d7cebf}\n.trust-strip>div:last-child{border:0}\n.trust-number{font-family:Georgia,serif;font-size:25px;color:var(--clay)}\n.trust-strip p{display:grid;margin:0;line-height:1.6}\n.trust-strip strong{font-size:13px;color:var(--forest)}\n.trust-strip small{font-size:10px;color:var(--muted)}\n.section-wrap{padding-left:clamp(22px,8vw,120px);padding-right:clamp(22px,8vw,120px)}\n.products-section{padding-top:100px;padding-bottom:100px}\n.section-heading{display:flex;align-items:end;justify-content:space-between;gap:40px;margin-bottom:42px}\n.section-heading h2,.story-copy h2,.track-copy h2{font-size:clamp(32px,4vw,52px);line-height:1.4;letter-spacing:-.045em;margin:10px 0 0;color:var(--forest)}\n.section-heading h2 em,.story-copy h2 em,.track-copy h2 em{color:var(--clay)}\n.section-heading>p{max-width:440px;margin:0;color:var(--muted);font-size:12px;line-height:2.1}\n.catalog-toolbar{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:25px}\n.category-filters{display:flex;gap:8px;flex-wrap:wrap}\n.filter-chip{border:1px solid var(--line);border-radius:999px;padding:7px 16px;background:transparent;color:#686b61;font-size:11px}\n.filter-chip.active,.filter-chip:hover{background:var(--forest);color:white;border-color:var(--forest)}\n.catalog-count{font-size:11px;color:var(--muted)}\n.product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:30px 20px}\n.product-card{min-width:0;position:relative}\n.product-photo{height:245px;background:#eee8dc;padding:12px;position:relative;box-shadow:0 10px 24px rgba(36,42,34,.07)}\n.product-photo:after{content:\"\";position:absolute;inset:12px;border:1px solid rgba(255,255,255,.55);pointer-events:none}\n.product-photo img{width:100%;height:100%;object-fit:cover}\n.product-category{font-size:10px;color:var(--clay);margin:18px 0 3px}\n.product-card h3{font-size:17px;color:var(--forest);margin:0;letter-spacing:-.03em}\n.product-description{font-size:11px;line-height:1.9;color:var(--muted);min-height:43px;margin:6px 0 12px}\n.product-meta{display:flex;justify-content:space-between;align-items:center;gap:8px;padding-top:10px;border-top:1px solid var(--line)}\n.product-price{font-size:12px;font-weight:700;color:var(--forest)}\n.product-price small{display:block;font-size:9px;color:var(--muted);font-weight:400}\n.stock-label{font-size:9px;color:#8a806f}\n.add-button{width:100%;margin-top:12px;border:1px solid var(--forest);border-radius:999px;background:transparent;color:var(--forest);padding:9px 12px;font-size:11px}\n.add-button:hover{background:var(--forest);color:#fff}\n.add-button:disabled{opacity:.4;cursor:not-allowed}\n.loading-state,.empty-cart{padding:35px;text-align:center;color:var(--muted);font-size:13px;background:#f1ede4;border-radius:16px;grid-column:1/-1}\n.story-section{display:grid;grid-template-columns:1fr 1fr;min-height:510px;background:#eae4d8}\n.story-image{position:relative;min-height:510px;padding:36px 0 36px 36px}\n.story-image img{width:100%;height:100%;object-fit:cover;box-shadow:var(--shadow)}\n.image-caption{position:absolute;bottom:55px;right:58px;background:var(--paper);padding:8px 15px;font-size:10px;color:var(--forest)}\n.story-copy{padding:70px clamp(30px,8vw,120px) 65px 55px;align-self:center}\n.story-copy h2{font-size:clamp(34px,4vw,52px);margin:13px 0 20px}\n.story-copy p{font-size:13px;line-height:2.2;color:#65685e;margin:0 0 14px}\n.signature{margin-top:28px;color:var(--forest);font-size:22px;font-weight:800}\n.signature span{display:block;font-size:10px;font-weight:400;color:var(--muted)}\n.how-section{padding-top:95px;padding-bottom:100px}\n.section-heading.compact{margin-bottom:34px}\n.steps-grid{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}\n.steps-grid article{padding:28px 25px 30px;border-left:1px solid var(--line)}\n.steps-grid article:last-child{border:0}\n.steps-grid article>span{font-family:Georgia,serif;font-size:30px;color:var(--clay)}\n.steps-grid h3{font-size:16px;color:var(--forest);margin:7px 0}\n.steps-grid p{font-size:11px;line-height:2;color:var(--muted);margin:0;max-width:280px}\n.track-section{background:#e9e3d7;padding:60px clamp(22px,8vw,120px);display:grid;grid-template-columns:1fr 1fr;gap:55px;align-items:center}\n.track-copy h2{font-size:38px}\n.track-copy p{font-size:12px;color:var(--muted);max-width:380px;line-height:2.1}\n.track-form{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.track-form label,.checkout-form label,.login-card label{display:grid;gap:6px;font-size:11px;color:#606459}\n.track-form input,.checkout-form input,.checkout-form textarea,.checkout-form select,.login-card input,.admin-form input,.admin-form select,.admin-form textarea{width:100%;border:1px solid #d8d1c4;background:#fbfaf6;border-radius:10px;padding:11px 13px;outline:none;color:var(--ink);font-size:12px}\n.track-form input:focus,.checkout-form input:focus,.checkout-form textarea:focus,.checkout-form select:focus,.login-card input:focus,.admin-form input:focus,.admin-form select:focus,.admin-form textarea:focus{border-color:var(--moss);box-shadow:0 0 0 3px rgba(111,121,87,.12)}\n.track-form .button{grid-column:1/-1}\n.form-feedback{font-size:11px;color:var(--clay);margin:0;min-height:20px}\n.form-feedback.success{color:#486c4b}\n.contact-band{padding:48px clamp(22px,8vw,120px);background:var(--forest);color:#f5f0e6;display:flex;justify-content:space-between;align-items:center;gap:30px}\n.contact-band h2{font-size:clamp(22px,3vw,34px);margin:8px 0 0;letter-spacing:-.04em}\n.contact-band .eyebrow{color:#d7b98e}\n.contact-meta{display:grid;gap:2px;text-align:left}\n.contact-meta span{font-size:10px;color:#c4c5b7}\n.contact-meta strong{font-size:16px;color:#e5c99d;direction:ltr}\n.contact-meta small{font-size:10px;color:#c4c5b7}\n.site-footer{padding:28px clamp(22px,5vw,76px);display:flex;align-items:center;justify-content:space-between;gap:20px;background:#f0ece3}\n.footer-brand{min-width:auto}\n.site-footer p,.footer-copy{font-size:10px;color:var(--muted);margin:0}\n.drawer-backdrop,.modal-backdrop{position:fixed;inset:0;background:rgba(21,29,23,.55);z-index:40;backdrop-filter:blur(3px)}\n.cart-drawer{position:fixed;z-index:41;top:0;bottom:0;right:0;width:min(440px,100%);background:var(--paper);padding:26px;display:flex;flex-direction:column;transform:translateX(105%);transition:transform .25s ease;box-shadow:-20px 0 50px rgba(0,0,0,.14)}\n.cart-drawer.open{transform:translateX(0)}\n.drawer-head,.modal-head{display:flex;justify-content:space-between;align-items:center;padding-bottom:18px;border-bottom:1px solid var(--line)}\n.drawer-head h2,.modal-head h2{font-size:25px;color:var(--forest);margin:3px 0}\n.close-button{width:38px;height:38px;border:1px solid var(--line);border-radius:50%;background:transparent;color:var(--forest);font-size:24px;line-height:1}\n.cart-lines{overflow:auto;flex:1;padding:15px 0}\n.cart-line{display:grid;grid-template-columns:1fr auto;gap:10px;padding:14px 0;border-bottom:1px solid var(--line)}\n.cart-line strong{display:block;color:var(--forest);font-size:13px}\n.cart-line small{font-size:10px;color:var(--muted)}\n.qty-control{display:flex;align-items:center;gap:9px}\n.qty-control button{width:28px;height:28px;border:1px solid var(--line);background:#fff;border-radius:50%;color:var(--forest)}\n.qty-control b{font-size:12px;min-width:25px;text-align:center}\n.drawer-footer{padding-top:15px;border-top:1px solid var(--line)}\n.cart-estimate{display:flex;justify-content:space-between;align-items:center;font-size:12px}\n.cart-estimate strong{color:var(--forest)}\n.drawer-footer p{font-size:10px;color:var(--muted);line-height:1.9}\n.full-width{width:100%}\n.modal-backdrop{display:grid;place-items:center;padding:18px;overflow:auto}\n.checkout-modal,.success-modal{width:min(620px,100%);max-height:calc(100vh - 36px);overflow:auto;background:var(--paper);border-radius:22px;padding:28px;box-shadow:var(--shadow)}\n.checkout-form{display:grid;gap:14px;padding-top:20px}\n.checkout-form .form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.checkout-form textarea{resize:vertical;min-height:76px}\n.optional{font-size:9px;color:var(--muted)}\n.checkout-notice{padding:12px 14px;background:#eee8dc;border-right:3px solid var(--clay);font-size:11px;line-height:2;color:#5f6258}\n.success-modal{width:min(440px,100%);text-align:center;padding:35px}\n.success-mark{width:54px;height:54px;display:grid;place-items:center;border-radius:50%;margin:0 auto 14px;background:#e6eadf;color:#4d684d;font-size:26px}\n.success-modal h2{font-size:28px;color:var(--forest);margin:8px 0}\n.success-modal>p{font-size:12px;color:var(--muted);line-height:2}\n.order-code{background:#f0ece3;padding:15px;border-radius:14px;margin:20px 0;display:grid;gap:4px}\n.order-code small{font-size:10px;color:var(--muted)}\n.order-code strong{font-size:21px;letter-spacing:.08em;color:var(--forest);direction:ltr}\n.order-code button{justify-self:center;border:0;background:transparent;color:var(--clay);font-size:11px}\n@media(max-width:1050px){.product-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.hero{padding-right:7vw;padding-left:7vw}.hero-visual{width:340px;height:340px}}\n@media(max-width:760px){\n  .site-header{height:70px;padding:0 16px}.desktop-nav,.icon-link{display:none}.brand{min-width:0}.brand-mark{width:37px;height:37px}\n  .hero{grid-template-columns:1fr;padding:54px 24px 72px;gap:38px}.hero-copy{max-width:100%}.hero h1{font-size:47px}.hero-copy>p{font-size:12px}\n  .hero-visual{width:270px;height:270px;margin:0 auto}.hero-photo-frame{inset:12px}.hero-stamp{width:94px;height:94px;left:-16px;bottom:5px}.hero-stamp span{font-size:22px}.hero-stamp small{font-size:8px}.orbit-one{width:310px;height:310px;top:-8px;left:-18px}.orbit-two{width:340px;height:340px;top:-22px;left:-32px}\n  .trust-strip{padding:20px 14px;gap:5px}.trust-strip>div{gap:7px;padding:0 5px}.trust-number{font-size:18px}.trust-strip strong{font-size:10px}.trust-strip small{font-size:8px}\n  .products-section{padding-top:65px;padding-bottom:65px}.section-heading{display:block;margin-bottom:25px}.section-heading>p{margin-top:14px}.section-heading h2{font-size:37px}\n  .catalog-toolbar{align-items:flex-start;flex-direction:column}.product-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 12px}.product-photo{height:175px;padding:8px}.product-photo:after{inset:8px}.product-card h3{font-size:14px}.product-description{font-size:10px;min-height:50px}.product-meta{align-items:flex-start;flex-direction:column}.add-button{font-size:10px;padding:8px}\n  .story-section{grid-template-columns:1fr}.story-image{min-height:300px;padding:22px 22px 0}.story-copy{padding:35px 24px 45px}.story-copy h2{font-size:38px}\n  .how-section{padding-top:60px;padding-bottom:65px}.steps-grid{grid-template-columns:1fr}.steps-grid article{border-left:0;border-bottom:1px solid var(--line);padding:20px 4px}.steps-grid article:last-child{border-bottom:0}\n  .track-section{grid-template-columns:1fr;gap:20px;padding:42px 22px}.track-form{grid-template-columns:1fr}.track-form .button{grid-column:auto}\n  .contact-band{align-items:flex-start;flex-direction:column;padding:36px 22px}.contact-meta{text-align:right}\n  .site-footer{flex-wrap:wrap}.site-footer p{order:3;width:100%}\n  .checkout-modal{padding:20px}.checkout-form .form-row{grid-template-columns:1fr}\n}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{transition:none!important}}\n\n.image-missing{background:linear-gradient(135deg,#e5ddce,#f2ede3);position:relative}\n.image-missing:before{content:\"پادناکِشت\";position:absolute;inset:0;display:grid;place-items:center;color:#8d8a7c;font-size:14px}\n.toast{position:fixed;z-index:80;bottom:22px;left:50%;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#263b2d;color:#fff;padding:11px 20px;border-radius:999px;font-size:11px;box-shadow:var(--shadow);transition:opacity .2s,transform .2s}\n.toast.visible{opacity:1;transform:translate(-50%,0)}\n@media(max-width:600px){.toast{width:max-content;max-width:calc(100% - 30px);text-align:center;white-space:normal}}\n\n.image-note{position:absolute;z-index:2;left:20px;bottom:20px;background:rgba(251,249,244,.92);color:#716b5e;border:1px solid rgba(255,255,255,.7);border-radius:999px;padding:4px 9px;font-size:9px}\n.hero-photo-frame:after{content:\"عکس نمایشی\";position:absolute;left:14px;bottom:14px;background:rgba(251,249,244,.92);color:#716b5e;padding:4px 10px;border-radius:999px;font-size:9px}\n\n[hidden]{display:none!important}\n.credits-wrap{max-width:900px;margin:70px auto;padding:0 24px 80px}\n.credits-wrap h1{font-size:clamp(34px,5vw,52px);color:var(--forest);margin:8px 0 16px}\n.credits-intro{max-width:760px;font-size:13px;line-height:2.1;color:var(--muted);margin-bottom:30px}\n.credits-list{list-style:none;padding:0;margin:0;border-top:1px solid var(--line)}\n.credits-list li{display:grid;grid-template-columns:1fr 1.2fr auto;gap:18px;align-items:center;padding:14px 4px;border-bottom:1px solid var(--line);font-size:12px}\n.credits-list strong{color:var(--forest)}\n.credits-list span{color:var(--muted);font-size:11px}\n.credits-list a,.credits-license a{color:var(--clay);text-decoration:underline;text-underline-offset:3px}\n.credits-license{font-size:11px;color:var(--muted);margin-top:24px}\n@media(max-width:620px){.credits-wrap{margin:38px auto}.credits-list li{grid-template-columns:1fr auto;gap:4px 12px}.credits-list li span{grid-column:1}.credits-list li a{grid-column:2;grid-row:1/3}}\n\n.no-scroll{overflow:hidden}\n.image-missing img{visibility:hidden}\n","admin.css":".admin-body{background:#f2eee5;min-height:100vh}\n.admin-header{height:76px;background:var(--paper);padding:0 clamp(18px,6vw,90px);display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}\n.back-link{font-size:11px;color:var(--clay)}\n.admin-wrap{max-width:1100px;margin:42px auto;padding:0 20px 70px}\n.login-card{max-width:430px;margin:70px auto;background:var(--paper);padding:34px;border-radius:20px;box-shadow:var(--shadow)}\n.login-card h1,.admin-title h1{font-size:29px;color:var(--forest);margin:6px 0}\n.login-card>p{font-size:12px;color:var(--muted);margin-bottom:24px}\n.login-card form{display:grid;gap:14px}\n.admin-title{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:26px}\n.admin-tabs{display:flex;gap:8px;border-bottom:1px solid var(--line);margin-bottom:24px}\n.admin-tabs button{border:0;border-bottom:2px solid transparent;background:transparent;padding:12px 18px;color:var(--muted);font-size:12px}\n.admin-tabs button.active{color:var(--forest);border-color:var(--clay);font-weight:700}\n.admin-panel{background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:22px;margin-bottom:22px}\n.panel-title{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}\n.panel-title h2{font-size:18px;color:var(--forest);margin:0}\n.text-button{border:0;background:transparent;color:var(--clay);font-size:11px}\n.admin-order{border:1px solid var(--line);border-radius:14px;padding:17px;margin:12px 0;background:#fff}\n.admin-order-head{display:flex;justify-content:space-between;gap:15px;align-items:center}\n.admin-order h3{font-size:15px;color:var(--forest);margin:0}\n.order-status{font-size:10px;color:#815a3e;background:#f1e7d8;padding:4px 10px;border-radius:999px}\n.admin-order p{font-size:11px;line-height:1.9;color:#66695f;margin:8px 0}\n.admin-order-form,.admin-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:14px}\n.admin-form label,.admin-order-form label{display:grid;gap:5px;font-size:10px;color:var(--muted)}\n.admin-order-form .wide,.admin-form .wide{grid-column:1/-1}\n.admin-order-form button,.admin-form button{align-self:end}\n.product-admin-row{display:grid;grid-template-columns:74px 1fr auto;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid var(--line)}\n.product-admin-row img{width:74px;height:62px;object-fit:cover;border-radius:9px;background:#eee8dc}\n.product-admin-row strong{font-size:12px;color:var(--forest);display:block}\n.product-admin-row small{font-size:10px;color:var(--muted)}\n.product-edit{background:transparent;border:1px solid var(--line);border-radius:999px;padding:7px 13px;color:var(--forest);font-size:10px}\n.product-editor{margin:12px 0 20px;padding:18px;background:#f2eee5;border-radius:14px}\n.product-editor h3{font-size:14px;color:var(--forest);margin:0 0 12px}\n.admin-footnote{font-size:10px;line-height:1.9;color:var(--muted);padding:0 8px}\n@media(max-width:680px){.admin-wrap{margin:24px auto}.admin-panel{padding:15px}.admin-title{align-items:flex-start}.admin-title h1{font-size:23px}.admin-order-form,.admin-form{grid-template-columns:1fr}.admin-order-form .wide,.admin-form .wide{grid-column:auto}.product-admin-row{grid-template-columns:58px 1fr auto}.product-admin-row img{width:58px;height:54px}.login-card{margin:40px auto;padding:24px}}\n","app.js":"(() => {\n  const $ = id => document.getElementById(id);\n  const state = { products:[], cart:new Map(), category:\"all\" };\n  const digits = n => new Intl.NumberFormat(\"fa-IR\").format(Number(n||0));\n  const money = n => digits(n) + \" تومان\";\n  const escapeHtml = value => String(value ?? \"\").replace(/[&<>\"']/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\n  const readCart = () => {\n    try {\n      const raw = JSON.parse(localStorage.getItem(\"padnakasht-cart\") || \"[]\");\n      state.cart = new Map(raw.filter(x => x && typeof x.id===\"string\" && Number(x.qty)>0).map(x => [x.id,Number(x.qty)]));\n    } catch { state.cart = new Map(); }\n  };\n  const saveCart = () => localStorage.setItem(\"padnakasht-cart\",JSON.stringify([...state.cart].map(([id,qty])=>({id,qty}))));\n  const quantityStep = p => String(p.unit||\"\").includes(\"کیلوگرم\") ? 0.5 : 1;\n  const quantityLabel = n => digits(n);\n  const statusText = status => ({\n    new:\"در انتظار بررسی\",reviewed:\"در حال هماهنگی\",confirmed:\"سفارش تأیید شد\",\n    preparing:\"در حال آماده‌سازی\",shipped:\"ارسال شده\",completed:\"تکمیل شده\",cancelled:\"لغو شده\"\n  })[status] || \"در حال بررسی\";\n\n  const API_ENDPOINT = new URL(\"./\",window.location.href).toString();\n  const PUBLIC_API_KEY = \"sb_publishable_Ttbile4UN76kwsZ0chw3DA_HfaqPUjA\";\n  async function api(path,options={}) {\n    let body={};\n    if(options.body){try{body=JSON.parse(options.body);}catch{body={};}}\n    const response=await fetch(API_ENDPOINT,{method:\"POST\",headers:{\"content-type\":\"application/json\",\"apikey\":PUBLIC_API_KEY},body:JSON.stringify({path,method:options.method||\"GET\",body})});\n    let data={};try{data=await response.json();}catch{}\n    if(!response.ok)throw new Error(data.error||\"درخواست انجام نشد.\");\n    return data;\n  }\n  function feedback(id,message,success=false) {\n    const el=$(id); if(!el)return;\n    el.textContent=message; el.classList.toggle(\"success\",success);\n  }\n  function imageFallbacks(root) {\n    root.querySelectorAll(\"img\").forEach(img=>img.addEventListener(\"error\",()=>{img.parentElement.classList.add(\"image-missing\");},{once:true}));\n  }\n  function renderFilters() {\n    const categories=[\"all\",...new Set(state.products.map(p=>p.category).filter(Boolean))];\n    $(\"category-filters\").innerHTML=categories.map(c=>'<button class=\"filter-chip '+(state.category===c?\"active\":\"\")+'\" data-category=\"'+escapeHtml(c)+'\" type=\"button\">'+(c===\"all\"?\"همه محصولات\":escapeHtml(c))+\"</button>\").join(\"\");\n    $(\"category-filters\").querySelectorAll(\"button\").forEach(button=>button.addEventListener(\"click\",()=>{\n      state.category=button.dataset.category;renderFilters();renderProducts();\n    }));\n  }\n  function renderProducts() {\n    const list=state.products.filter(p=>state.category===\"all\"||p.category===state.category);\n    $(\"catalog-count\").textContent=digits(list.length)+\" محصول\";\n    if(!list.length){$(\"product-grid\").innerHTML='<div class=\"loading-state\">در این گروه هنوز محصولی ثبت نشده است.</div>';return;}\n    $(\"product-grid\").innerHTML=list.map(p=>{\n      const unavailable=p.stock!==null && Number(p.stock)<=0;\n      const stockText=p.stock===null?\"موجودی پس از ثبت درخواست بررسی می‌شود\":(unavailable?\"فعلاً ناموجود\":\"موجودی: \"+digits(p.stock)+\" \"+escapeHtml(p.unit));\n      const price=p.price_toman===null?\"قیمت پس از هماهنگی\":money(p.price_toman);\n      return '<article class=\"product-card\"><div class=\"product-photo\"><img loading=\"lazy\" src=\"'+escapeHtml(p.image||\"\")+'\" alt=\"'+escapeHtml(p.name)+'\"><span class=\"image-note\">تصویر نمایشی</span></div>'+\n        '<div class=\"product-category\">'+escapeHtml(p.category||\"محصول محلی\")+'</div><h3>'+escapeHtml(p.name)+'</h3>'+\n        '<p class=\"product-description\">'+escapeHtml(p.description||\"محصولی از تولیدکنندگان پادنا.\")+'</p>'+\n        '<div class=\"product-meta\"><div class=\"product-price\">'+price+'<small>به‌ازای هر '+escapeHtml(p.unit)+'</small></div><span class=\"stock-label\">'+stockText+'</span></div>'+\n        '<button class=\"add-button\" data-add=\"'+escapeHtml(p.id)+'\" type=\"button\" '+(unavailable?\"disabled\":\"\")+'>افزودن به سبد</button></article>';\n    }).join(\"\");\n    imageFallbacks($(\"product-grid\"));\n    $(\"product-grid\").querySelectorAll(\"[data-add]\").forEach(button=>button.addEventListener(\"click\",()=>addToCart(button.dataset.add)));\n  }\n  function addToCart(id) {\n    const product=state.products.find(p=>p.id===id); if(!product)return;\n    const step=quantityStep(product), next=Number(((state.cart.get(id)||0)+step).toFixed(2));\n    if(product.stock!==null && next>Number(product.stock)){toast(\"موجودی این محصول برای این مقدار کافی نیست.\");return;}\n    state.cart.set(id,next);saveCart();renderCart();toast(\"به سبد خرید اضافه شد.\");\n  }\n  function toast(message) {\n    let el=$(\"toast\");\n    if(!el){el=document.createElement(\"div\");el.id=\"toast\";el.className=\"toast\";document.body.appendChild(el);}\n    el.textContent=message;el.classList.add(\"visible\");\n    window.clearTimeout(toast.timer);toast.timer=window.setTimeout(()=>el.classList.remove(\"visible\"),2600);\n  }\n  function cartItems() {\n    return [...state.cart.entries()].map(([id,qty])=>({product:state.products.find(p=>p.id===id),qty})).filter(x=>x.product);\n  }\n  function renderCart() {\n    const items=cartItems();\n    const count=items.reduce((sum,x)=>sum+x.qty,0);\n    $(\"cart-count\").textContent=digits(count);\n    $(\"cart-lines\").innerHTML=items.length?items.map(({product:p,qty})=>{\n      return '<div class=\"cart-line\"><div><strong>'+escapeHtml(p.name)+'</strong><small>'+quantityLabel(qty)+' '+escapeHtml(p.unit)+'</small></div>'+\n        '<div class=\"qty-control\"><button type=\"button\" data-dec=\"'+escapeHtml(p.id)+'\" aria-label=\"کم کردن\">−</button><b>'+quantityLabel(qty)+'</b><button type=\"button\" data-inc=\"'+escapeHtml(p.id)+'\" aria-label=\"زیاد کردن\">+</button></div></div>';\n    }).join(\"\"):'<div class=\"empty-cart\">هنوز محصولی انتخاب نکرده‌اید.</div>';\n    const allPriced=items.length && items.every(x=>x.product.price_toman!==null);\n    const subtotal=items.reduce((sum,x)=>sum+Math.round(Number(x.product.price_toman||0)*x.qty),0);\n    $(\"cart-subtotal\").textContent=allPriced?money(subtotal):\"پس از تأیید قیمت\";\n    $(\"checkout-open\").disabled=!items.length;\n    $(\"cart-lines\").querySelectorAll(\"[data-dec]\").forEach(button=>button.addEventListener(\"click\",()=>{\n      const p=state.products.find(x=>x.id===button.dataset.dec),step=quantityStep(p),next=Number(((state.cart.get(p.id)||0)-step).toFixed(2));\n      if(next<=0)state.cart.delete(p.id);else state.cart.set(p.id,next);\n      saveCart();renderCart();\n    }));\n    $(\"cart-lines\").querySelectorAll(\"[data-inc]\").forEach(button=>button.addEventListener(\"click\",()=>addToCart(button.dataset.inc)));\n  }\n  function openDrawer() {\n    $(\"drawer-backdrop\").hidden=false;$(\"cart-drawer\").classList.add(\"open\");$(\"cart-drawer\").setAttribute(\"aria-hidden\",\"false\");document.body.classList.add(\"no-scroll\");\n  }\n  function closeDrawer() {\n    $(\"cart-drawer\").classList.remove(\"open\");$(\"cart-drawer\").setAttribute(\"aria-hidden\",\"true\");$(\"drawer-backdrop\").hidden=true;document.body.classList.remove(\"no-scroll\");\n  }\n  function openModal(id) { $(id).hidden=false;document.body.classList.add(\"no-scroll\"); }\n  function closeModal(id) { $(id).hidden=true;document.body.classList.remove(\"no-scroll\"); }\n  function showSuccess(data) {\n    $(\"success-code\").textContent=data.order.id;\n    $(\"success-message\").textContent=data.message;\n    closeModal(\"checkout-modal\");closeDrawer();openModal(\"success-modal\");\n  }\n  async function loadProducts() {\n    try {\n      const data=await api(\"/api/products\");\n      state.products=data.products||[];\n      state.cart=new Map([...state.cart].filter(([id])=>state.products.some(p=>p.id===id)));\n      saveCart();renderFilters();renderProducts();renderCart();\n    } catch(error) {\n      $(\"product-grid\").innerHTML='<div class=\"loading-state\">دریافت فهرست محصولات انجام نشد. کمی بعد صفحه را تازه کنید.</div>';\n      $(\"catalog-count\").textContent=\"اتصال برقرار نشد\";\n    }\n  }\n\n  $(\"cart-open\").addEventListener(\"click\",openDrawer);\n  $(\"cart-close\").addEventListener(\"click\",closeDrawer);\n  $(\"drawer-backdrop\").addEventListener(\"click\",closeDrawer);\n  $(\"checkout-open\").addEventListener(\"click\",()=>{\n    if(!state.cart.size)return;\n    openModal(\"checkout-modal\");\n  });\n  $(\"checkout-close\").addEventListener(\"click\",()=>closeModal(\"checkout-modal\"));\n  $(\"checkout-modal\").addEventListener(\"click\",event=>{if(event.target===$(\"checkout-modal\"))closeModal(\"checkout-modal\");});\n  $(\"success-close\").addEventListener(\"click\",()=>{closeModal(\"success-modal\");window.scrollTo({top:0,behavior:\"smooth\"});});\n  $(\"success-modal\").addEventListener(\"click\",event=>{if(event.target===$(\"success-modal\"))closeModal(\"success-modal\");});\n  $(\"copy-order-code\").addEventListener(\"click\",async()=>{\n    try{await navigator.clipboard.writeText($(\"success-code\").textContent);toast(\"کد سفارش کپی شد.\");}\n    catch{toast(\"کد سفارش را به‌صورت دستی کپی کنید.\");}\n  });\n\n  $(\"checkout-form\").addEventListener(\"submit\",async event=>{\n    event.preventDefault();\n    const form=event.currentTarget,button=form.querySelector('button[type=\"submit\"]');\n    const fd=new FormData(form);\n    const payload={\n      customerName:fd.get(\"customerName\"),phone:fd.get(\"phone\"),city:fd.get(\"city\"),\n      address:fd.get(\"address\"),deliveryMethod:fd.get(\"deliveryMethod\"),notes:fd.get(\"notes\"),\n      items:cartItems().map(x=>({productId:x.product.id,quantity:x.qty}))\n    };\n    button.disabled=true;button.textContent=\"در حال ثبت درخواست…\";feedback(\"checkout-feedback\",\"\");\n    try{\n      const data=await api(\"/api/orders\",{method:\"POST\",body:JSON.stringify(payload)});\n      state.cart.clear();saveCart();renderCart();form.reset();showSuccess(data);\n    }catch(error){feedback(\"checkout-feedback\",error.message);}\n    finally{button.disabled=false;button.textContent=\"ثبت درخواست خرید\";}\n  });\n\n  $(\"track-form\").addEventListener(\"submit\",async event=>{\n    event.preventDefault();const form=event.currentTarget,fd=new FormData(form),button=form.querySelector(\"button\");\n    button.disabled=true;feedback(\"track-feedback\",\"در حال بررسی…\");\n    try{\n      const data=await api(\"/api/order-lookup\",{method:\"POST\",body:JSON.stringify({code:fd.get(\"code\"),phone:fd.get(\"phone\")})});\n      const o=data.order;\n      let amount=o.totalToman===null?\"مبلغ نهایی هنوز تأیید نشده\":money(o.totalToman);\n      feedback(\"track-feedback\",\"وضعیت: \"+statusText(o.status)+\" · \"+amount,true);\n    }catch(error){feedback(\"track-feedback\",error.message);}\n    finally{button.disabled=false;}\n  });\n\n  readCart();renderCart();loadProducts();\n})();","admin.js":"(() => {\n  const $=id=>document.getElementById(id);\n  const escapeHtml=value=>String(value??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\n  const digits=n=>new Intl.NumberFormat(\"fa-IR\").format(Number(n||0));\n  const money=n=>n===null||n===undefined?\"تأیید نشده\":digits(n)+\" تومان\";\n  const statusText=s=>({new:\"در انتظار بررسی\",reviewed:\"در حال هماهنگی\",confirmed:\"تأیید شده\",preparing:\"در حال آماده‌سازی\",shipped:\"ارسال شده\",completed:\"تکمیل شده\",cancelled:\"لغو شده\"})[s]||s;\n  const API_ENDPOINT=new URL(\"./\",window.location.href).toString();\n  const PUBLIC_API_KEY=\"sb_publishable_Ttbile4UN76kwsZ0chw3DA_HfaqPUjA\";\n  const api=async(path,options={})=>{\n    let body={};if(options.body){try{body=JSON.parse(options.body);}catch{body={};}}\n    const token=sessionStorage.getItem(\"padna-admin-session\")||\"\";\n    const headers={\"content-type\":\"application/json\",\"apikey\":PUBLIC_API_KEY};\n    if(token)headers[\"x-admin-session\"]=token;\n    const response=await fetch(API_ENDPOINT,{method:\"POST\",headers,body:JSON.stringify({path,method:options.method||\"GET\",body})});\n    let data={};try{data=await response.json();}catch{}\n    if(!response.ok)throw new Error(data.error||\"درخواست انجام نشد.\");\n    return data;\n  };\n  const feedback=(id,message,success=false)=>{const el=$(id);if(!el)return;el.textContent=message;el.classList.toggle(\"success\",success);};\n  function showDashboard(){\n    $(\"login-card\").hidden=true;$(\"setup-card\").hidden=true;$(\"admin-dashboard\").hidden=false;\n    loadOrders();loadProducts();\n  }\n  function showLogin(){\n    $(\"admin-dashboard\").hidden=true;$(\"setup-card\").hidden=true;$(\"login-card\").hidden=false;\n  }\n  function showSetup(){\n    $(\"admin-dashboard\").hidden=true;$(\"login-card\").hidden=true;$(\"setup-card\").hidden=false;\n  }\n  async function checkSession(){\n    try{\n      const d=await api(\"/api/admin/session\");\n      if(d.authenticated)showDashboard();\n      else if(d.setupRequired)showSetup();\n      else showLogin();\n    }catch(error){\n      showLogin();feedback(\"login-feedback\",error.message);\n    }\n  }\n  $(\"setup-form\").addEventListener(\"submit\",async event=>{\n    event.preventDefault();\n    const form=event.currentTarget,fd=new FormData(form),button=form.querySelector(\"button\");\n    const password=String(fd.get(\"password\")||\"\"),confirm=String(fd.get(\"passwordConfirm\")||\"\");\n    if(password!==confirm){feedback(\"setup-feedback\",\"گذرواژه و تکرار آن یکسان نیستند.\");return;}\n    button.disabled=true;button.textContent=\"در حال راه‌اندازی…\";feedback(\"setup-feedback\",\"\");\n    try{\n      const data=await api(\"/api/admin/setup\",{method:\"POST\",body:JSON.stringify({setupToken:fd.get(\"setupToken\"),password})});\n      form.reset();showLogin();feedback(\"login-feedback\",data.message||\"گذرواژه تنظیم شد؛ وارد شوید.\",true);\n    }catch(error){feedback(\"setup-feedback\",error.message);}\n    finally{button.disabled=false;button.textContent=\"راه‌اندازی پنل مدیریت\";}\n  });\n  $(\"login-form\").addEventListener(\"submit\",async event=>{\n    event.preventDefault();const form=event.currentTarget,button=form.querySelector(\"button\"),password=new FormData(form).get(\"password\");\n    button.disabled=true;feedback(\"login-feedback\",\"در حال بررسی…\");\n    try{const data=await api(\"/api/admin/login\",{method:\"POST\",body:JSON.stringify({password})});if(data.token)sessionStorage.setItem(\"padna-admin-session\",data.token);form.reset();showDashboard();}\n    catch(error){feedback(\"login-feedback\",error.message);}\n    finally{button.disabled=false;}\n  });\n  $(\"logout-button\").addEventListener(\"click\",async()=>{\n    try{await api(\"/api/admin/logout\",{method:\"POST\",body:\"{}\"});}catch{}\n    sessionStorage.removeItem(\"padna-admin-session\");\n    showLogin();\n  });\n  document.querySelectorAll(\".admin-tabs button\").forEach(button=>button.addEventListener(\"click\",()=>{\n    document.querySelectorAll(\".admin-tabs button\").forEach(x=>x.classList.toggle(\"active\",x===button));\n    $(\"orders-panel\").hidden=button.dataset.tab!==\"orders\";\n    $(\"products-panel\").hidden=button.dataset.tab!==\"products\";\n  }));\n\n  async function loadOrders(){\n    $(\"orders-list\").innerHTML='<p class=\"loading-state\">در حال دریافت سفارش‌ها…</p>';\n    try{\n      const data=await api(\"/api/admin/orders\");\n      if(!data.orders.length){$(\"orders-list\").innerHTML='<p class=\"loading-state\">هنوز درخواستی ثبت نشده است.</p>';return;}\n      $(\"orders-list\").innerHTML=data.orders.map(o=>{\n        const items=(o.items||[]).map(x=>escapeHtml(x.name)+\" × \"+digits(x.quantity)+\" \"+escapeHtml(x.unit)).join(\"، \");\n        const delivery=o.delivery_method===\"post\"?\"ارسال به شهرهای دیگر\":\"تحویل در اصفهان\";\n        return '<article class=\"admin-order\"><div class=\"admin-order-head\"><h3>'+escapeHtml(o.id)+' · '+escapeHtml(o.customer_name)+'</h3><span class=\"order-status\">'+statusText(o.status)+'</span></div>'+\n          '<p>'+escapeHtml(o.phone)+' · '+escapeHtml(o.city)+' · '+delivery+'</p><p>'+escapeHtml(o.address)+'</p><p>کالاها: '+items+'</p>'+\n          (o.notes?'<p>توضیحات مشتری: '+escapeHtml(o.notes)+'</p>':'')+\n          '<p>جمع کالاها: '+money(o.subtotal_toman)+' · ارسال: '+money(o.shipping_toman)+' · مبلغ نهایی: <b>'+money(o.total_toman)+'</b></p>'+\n          '<form class=\"admin-order-form\" data-id=\"'+escapeHtml(o.id)+'\">'+\n          '<label>وضعیت<select name=\"status\">'+\n          '<option value=\"reviewed\" '+(o.status===\"reviewed\"?\"selected\":\"\")+'>در حال هماهنگی</option>'+\n          '<option value=\"confirmed\" '+(o.status===\"confirmed\"?\"selected\":\"\")+'>تأیید سفارش</option>'+\n          '<option value=\"preparing\" '+(o.status===\"preparing\"?\"selected\":\"\")+'>در حال آماده‌سازی</option>'+\n          '<option value=\"shipped\" '+(o.status===\"shipped\"?\"selected\":\"\")+'>ارسال شده</option>'+\n          '<option value=\"completed\" '+(o.status===\"completed\"?\"selected\":\"\")+'>تکمیل شده</option>'+\n          '<option value=\"cancelled\" '+(o.status===\"cancelled\"?\"selected\":\"\")+'>لغو سفارش</option></select></label>'+\n          '<label>هزینه ارسال (تومان)<input name=\"shippingToman\" type=\"number\" min=\"0\" step=\"1\" value=\"'+(o.shipping_toman===null?\"\":escapeHtml(o.shipping_toman))+'\" placeholder=\"برای تأیید سفارش\"></label>'+\n          '<label class=\"wide\">یادداشت مدیر<textarea name=\"adminNote\" rows=\"2\" maxlength=\"500\">'+escapeHtml(o.admin_note||\"\")+'</textarea></label>'+\n          '<button class=\"button button-dark\" type=\"submit\">ذخیره تغییرات</button></form></article>';\n      }).join(\"\");\n      $(\"orders-list\").querySelectorAll(\".admin-order-form\").forEach(form=>form.addEventListener(\"submit\",saveOrder));\n    }catch(error){$(\"orders-list\").innerHTML='<p class=\"form-feedback\">'+escapeHtml(error.message)+'</p>';}\n  }\n  async function saveOrder(event){\n    event.preventDefault();const form=event.currentTarget,fd=new FormData(form),button=form.querySelector(\"button\");\n    const shippingRaw=String(fd.get(\"shippingToman\")||\"\").trim();\n    const payload={status:fd.get(\"status\"),shippingToman:shippingRaw===\"\"?null:Number(shippingRaw),adminNote:fd.get(\"adminNote\")};\n    button.disabled=true;button.textContent=\"در حال ذخیره…\";\n    try{await api(\"/api/admin/orders/\"+encodeURIComponent(form.dataset.id),{method:\"PATCH\",body:JSON.stringify(payload)});await loadOrders();}\n    catch(error){alert(error.message);}\n    finally{button.disabled=false;button.textContent=\"ذخیره تغییرات\";}\n  }\n  async function loadProducts(){\n    $(\"products-list\").innerHTML='<p class=\"loading-state\">در حال دریافت محصولات…</p>';\n    try{\n      const data=await api(\"/api/admin/products\");\n      $(\"products-list\").innerHTML=(data.products||[]).map(p=>\n        '<div class=\"product-admin-row\"><img src=\"'+escapeHtml(p.image)+'\" alt=\"\"><div><strong>'+escapeHtml(p.name)+'</strong><small>قیمت: '+money(p.price_toman)+' · موجودی: '+(p.stock===null?\"نامشخص\":digits(p.stock))+' '+escapeHtml(p.unit)+'</small></div><button class=\"product-edit\" type=\"button\" data-edit=\"'+escapeHtml(p.id)+'\">ویرایش</button></div>'+\n        '<div class=\"product-editor\" id=\"editor-'+escapeHtml(p.id)+'\" hidden><h3>ویرایش '+escapeHtml(p.name)+'</h3>'+\n        '<form class=\"admin-form\" data-id=\"'+escapeHtml(p.id)+'\">'+\n        '<label>نام محصول<input name=\"name\" value=\"'+escapeHtml(p.name)+'\" required maxlength=\"100\"></label>'+\n        '<label>دسته‌بندی<input name=\"category\" value=\"'+escapeHtml(p.category)+'\" maxlength=\"60\"></label>'+\n        '<label>قیمت روز (تومان)<input name=\"priceToman\" type=\"number\" min=\"1\" step=\"1\" value=\"'+(p.price_toman===null?\"\":escapeHtml(p.price_toman))+'\" placeholder=\"خالی = قیمت تأیید نشده\"></label>'+\n        '<label>موجودی<input name=\"stock\" type=\"number\" min=\"0\" step=\"0.01\" value=\"'+(p.stock===null?\"\":escapeHtml(p.stock))+'\" placeholder=\"خالی = موجودی نامشخص\"></label>'+\n        '<label>واحد فروش<input name=\"unit\" value=\"'+escapeHtml(p.unit)+'\" maxlength=\"30\" required></label>'+\n        '<label>مسیر تصویر<input name=\"image\" value=\"'+escapeHtml(p.image)+'\" placeholder=\"/images/name.jpg\"></label>'+\n        '<label class=\"wide\">توضیحات<textarea name=\"description\" rows=\"2\" maxlength=\"500\">'+escapeHtml(p.description)+'</textarea></label>'+\n        '<label><span><input name=\"active\" type=\"checkbox\" '+(p.active?\"checked\":\"\")+'> نمایش در فروشگاه</span></label>'+\n        '<button class=\"button button-dark\" type=\"submit\">ذخیره محصول</button></form></div>'\n      ).join(\"\");\n      $(\"products-list\").querySelectorAll(\"[data-edit]\").forEach(button=>button.addEventListener(\"click\",()=>{\n        const editor=$(\"editor-\"+button.dataset.edit);editor.hidden=!editor.hidden;\n      }));\n      $(\"products-list\").querySelectorAll(\".admin-form\").forEach(form=>form.addEventListener(\"submit\",saveProduct));\n    }catch(error){$(\"products-list\").innerHTML='<p class=\"form-feedback\">'+escapeHtml(error.message)+'</p>';}\n  }\n  async function saveProduct(event){\n    event.preventDefault();const form=event.currentTarget,fd=new FormData(form),button=form.querySelector(\"button\");\n    const price=String(fd.get(\"priceToman\")||\"\").trim(),stock=String(fd.get(\"stock\")||\"\").trim();\n    const payload={\n      name:fd.get(\"name\"),category:fd.get(\"category\"),unit:fd.get(\"unit\"),\n      description:fd.get(\"description\"),image:fd.get(\"image\"),\n      priceToman:price===\"\"?null:Number(price),stock:stock===\"\"?null:Number(stock),\n      active:form.elements.active.checked\n    };\n    button.disabled=true;button.textContent=\"در حال ذخیره…\";\n    try{await api(\"/api/admin/products/\"+encodeURIComponent(form.dataset.id),{method:\"PUT\",body:JSON.stringify(payload)});await loadProducts();}\n    catch(error){alert(error.message);}\n    finally{button.disabled=false;button.textContent=\"ذخیره محصول\";}\n  }\n  $(\"orders-refresh\").addEventListener(\"click\",loadOrders);\n  $(\"products-refresh\").addEventListener(\"click\",loadProducts);\n  checkSession();\n})();"};
const STATIC_TYPES:Record<string,string>={"index.html":"text/html; charset=utf-8","admin.html":"text/html; charset=utf-8","credits.html":"text/html; charset=utf-8","styles.css":"text/css; charset=utf-8","admin.css":"text/css; charset=utf-8","app.js":"text/javascript; charset=utf-8","admin.js":"text/javascript; charset=utf-8"};
const STATIC_HEADERS={
  "X-Content-Type-Options":"nosniff",
  "X-Frame-Options":"DENY",
  "Referrer-Policy":"strict-origin-when-cross-origin",
  "Permissions-Policy":"camera=(), microphone=(), geolocation=()",
  "Content-Security-Policy":"default-src 'self'; img-src 'self' data: https://images.pexels.com; style-src 'self'; script-src 'self'; connect-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'"
};
async function serveStatic(req:Request){
  const url=new URL(req.url);
  const prefix="/functions/v1/store-api";
  const remainder=decodeURIComponent(url.pathname.slice(prefix.length));
  let name=remainder.startsWith("/")?remainder.slice(1):remainder;
  name=name||"index.html";
  if(name.includes("/")||!Object.hasOwn(STATIC_TYPES,name))return new Response("Not found",{status:404,headers:STATIC_HEADERS});
  const content=STATIC_ASSETS[name];
  if(content===undefined)return new Response("Not found",{status:404,headers:STATIC_HEADERS});
  return new Response(req.method==="HEAD"?null:content,{status:200,headers:{...STATIC_HEADERS,"content-type":STATIC_TYPES[name],"cache-control":name.endsWith(".html")?"no-cache":"public, max-age=3600"}});
}
Deno.serve(async (req: Request) => {
  if (!SUPABASE_URL || !SERVICE_KEY) return json({error:"سرویس پایگاه داده پیکربندی نشده است."},503);
  if(req.method==="GET"||req.method==="HEAD")return await serveStatic(req);
  if(req.method!=="POST")return json({error:"Method Not Allowed"},405);
  if(req.headers.get("apikey")!==PUBLIC_API_KEY)return json({error:"کلید عمومی درخواست معتبر نیست."},401);
  let payload:any;
  try { payload=await req.json(); } catch { return json({error:"درخواست معتبر نیست."},400); }
  try { return await handle(payload,req); }
  catch (error) { return json({error:errorMessage(error)},500); }
});
